'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
const isHost=new URLSearchParams(location.search).has('host');
const KEY='nanikore-show-v1';
const PLAYER_COUNT=3;
const playerIds=()=>Array.from({length:PLAYER_COUNT},(_,i)=>i);
const BREAKS=[
 {icon:'✦',label:'むだ魔法',question:'いちばん使い道のない魔法は？',direction:'魔法の名前と、ものすごくどうでもいい効果を発表！',tag:'役に立ったら負け。'},
 {icon:'▣',label:'冷蔵庫の本音',question:'冷蔵庫を開けたら、ひと言しゃべった。何て言った？',direction:'冷蔵庫になりきって、ひと言でどうぞ。',tag:'言われたら、もう閉められない。'},
 {icon:'★',label:'どうでもいい自慢',question:'いちばんどうでもいい自慢を、ひとつ言って！',direction:'すごそうな顔で、自信満々に発表してね。',tag:'すごくないほど、なんやねん。'},
 {icon:'☀',label:'自分の祝日',question:'自分だけの祝日を作るなら、何の日？',direction:'その日は何をして過ごす？',tag:'国民はたぶん休めません。'},
 {icon:'⌂',label:'家の新ルール',question:'家にひとつ、変なルールを増やすなら？',direction:'家族が守れるかどうかも考えてね。',tag:'守る意味は、なくていい。'},
 {icon:'✧',label:'いらない発明',question:'誰も欲しがらなさそうな発明品は？',direction:'商品名と使い方を発表してね。',tag:'売れない理由も聞いてみよう。'},
 {icon:'♢',label:'スプーンの名前',question:'目の前のスプーンに名前をつけるなら？',direction:'名前をつけた理由もひと言。',tag:'スプーンは何も言いません。'},
 {icon:'⚡',label:'最弱ヒーロー',question:'絶対に戦わなそうなヒーローの名前は？',direction:'必殺技もあれば発表！',tag:'世界はたぶん平和。'},
 {icon:'◉',label:'宇宙人に説明',question:'宇宙人に「おにぎり」をひと言で説明するなら？',direction:'知らない相手にも伝わるかな？',tag:'海苔の説明が難しい。'},
 {icon:'✎',label:'いらない授業',question:'学校に絶対いらない授業を作るなら？',direction:'授業名と、何を学ぶかをどうぞ。',tag:'テストはありません。'},
 {icon:'▰',label:'プリンに謝罪',question:'食べたプリンに謝るなら、何と言う？',direction:'真剣な顔で謝ってください。',tag:'プリンは返ってこない。'},
 {icon:'☂',label:'変な天気',question:'明日、空から変なものが降るなら何？',direction:'そのとき持って行く物も教えて。',tag:'傘で防げるとは限らない。'},
 {icon:'▤',label:'どうでもいい機能',question:'スマホにいらない機能をひとつ足すなら？',direction:'何ができる機能か説明してね。',tag:'電池だけ減りそう。'},
 {icon:'⏰',label:'起きられない目覚まし',question:'絶対に起きられない目覚まし時計は？',direction:'どんなふうに起こすのか、やってみて。',tag:'寝坊は確定。'},
 {icon:'♛',label:'地味な世界記録',question:'世界記録にしたい、地味すぎる特技は？',direction:'できればその場で披露してね。',tag:'ギネスにはたぶん載らない。'},
 {icon:'↗',label:'二度見する看板',question:'道ばたで見たら二度見する看板の言葉は？',direction:'看板を読む人になりきってどうぞ。',tag:'通り過ぎられない。'},
 {icon:'✿',label:'動物のお仕事',question:'カバがコンビニで働いたら、何の担当？',direction:'働いている姿を想像してね。',tag:'レジは狭いかも。'},
 {icon:'♨',label:'変なメニュー',question:'喫茶店に絶対置いてなさそうなメニューは？',direction:'注文するときの言い方もどうぞ。',tag:'店員さんも困る。'},
 {icon:'✳',label:'謎の賞',question:'今日の3人に、謎の賞を贈るなら何賞？',direction:'誰に何賞か、理由も添えて。',tag:'トロフィーはありません。'},
 {icon:'¥',label:'1円でもいらない',question:'1円でも買いたくない商品は？',direction:'商品名と、売り文句を発表！',tag:'値段の問題じゃない。'},
 {icon:'✦',label:'地味な変身',question:'変身したのに誰も気づかない。何が変わった？',direction:'変身ポーズもつけてどうぞ。',tag:'たぶん元に戻らなくていい。'},
 {icon:'◈',label:'変な検定',question:'誰でも合格できそうな検定を作るなら？',direction:'合格条件をひとつ教えて。',tag:'合格率100％を目指そう。'},
 {icon:'☕',label:'お菓子の注意書き',question:'お菓子の袋に書いてあったら笑う注意書きは？',direction:'真面目な声で読んでみて。',tag:'読んでも食べます。'},
 {icon:'◎',label:'未来の遊び',question:'100年後に流行る、意味不明な遊びは？',direction:'遊び方を10秒で説明してね。',tag:'今から流行るかもしれない。'},
 {icon:'□',label:'ティッシュの使い道',question:'ティッシュ1枚を、いちばん大げさに使うなら？',direction:'壮大な作戦みたいに話して。',tag:'最後はたぶん捨てる。'},
 {icon:'✿',label:'変なペット名',question:'もし石をペットにしたら、名前は何？',direction:'その石の性格も教えてね。',tag:'お散歩は簡単。'},
 {icon:'○',label:'くだらない大会',question:'家で大会を開くなら、何を競う？',direction:'優勝の決め方も教えて。',tag:'審判も家族。'},
 {icon:'☆',label:'ありえない自己紹介',question:'初対面で言われたら困る自己紹介は？',direction:'その人になりきってひと言。',tag:'名前を聞きそびれそう。'},
 {icon:'◇',label:'謎の落とし物',question:'道で拾ったら困る、変な落とし物は？',direction:'持ち主を想像してみて。',tag:'交番の人もびっくり。'},
 {icon:'☘',label:'いらない能力',question:'できても自慢しにくい特殊能力は？',direction:'その力を見せるポーズもどうぞ。',tag:'平和すぎる能力。'}
];
function drawIds(ids,count){const a=[...ids];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a.slice(0,count);}
const drawQuestions=()=>drawIds(QUESTIONS.map(q=>q.id),10);
const drawBreaks=()=>drawIds(BREAKS.map((_,i)=>i),3);
let cfg={names:['りんか','さくら','ママ'],order:drawQuestions(),breakOrder:drawBreaks(),modes:{},spots:{},silent:true};
let state={phase:'setup',index:0,hint:0,scores:[0,0,0],revealed:false,awarded:[false,false,false],selected:[false,false,false],bonusAwarded:false,breakAwarded:[false,false,false],seed:Math.random(),verbal:false};
let history=[],hostWindow=null,hostVisible=false,recording=false,assetsReady=false,assetError=false,countdownTimer=null,countdownValue=3,previewId=null;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved?.cfg&&saved?.state&&saved.cfg.order?.length===10&&saved.cfg.order.every(id=>QUESTIONS.some(q=>q.id===id))){cfg=saved.cfg;state=saved.state;history=saved.history||[];if(state.phase==='countdown')state.phase='intro';}}catch{}
function addThirdPlayer(config,game){config.names[2]??='ママ';config.breakOrder??=drawBreaks();game.scores[2]??=0;game.awarded[2]??=false;game.selected[2]??=false;game.bonusAwarded??=false;if(!Array.isArray(game.breakAwarded)){const previous=game.breakAwarded;game.breakAwarded=playerIds().map(i=>i===previous);}game.breakAwarded[2]??=false;}
addThirdPlayer(cfg,state);
history.forEach(entry=>addThirdPlayer(entry.cfg,entry.state));
const question=()=>QUESTIONS.find(q=>q.id===cfg.order[state.index])||QUESTIONS[0];
const mode=()=>cfg.modes[question().id]||question().mode;
const isFinal=()=>state.index===cfg.order.length-1;
const points=()=>(3-state.hint)*(isFinal()?2:1);
const asset=id=>window.QUIZ_ASSETS?.[id]||`assets/${id}.${Number(id)>10?'webp':'png'}`;
function save(){try{localStorage.setItem(KEY,JSON.stringify({cfg,state,history}));}catch{}}
function sync(){if(hostWindow&&!hostWindow.closed)hostWindow.postMessage({kind:'quiz-state',cfg,state,history,assetsReady,assetError},location.origin==='null'?'*':location.origin);}
function change(fn,{remember=true}={}){const before=clone(state);if(remember){history.push(clone({cfg,state}));if(history.length>60)history.shift();}fn();save();render();sync();effects(before);}
function cue(text,correct=false){if(isHost)return;document.querySelector('.visual-cue')?.remove();const el=document.createElement('div');el.className='visual-cue'+(correct?' correct':'');el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),1050);}
 function effects(before){if(isHost)return;if(state.phase!==before.phase||state.index!==before.index){($('.interlude')||$('.stage')||$('.break-screen'))?.classList.add('round-enter');if(state.phase==='play')cue(isFinal()?'ラスト！ 得点2倍':question().simultaneous?'せーので回答！':`第 ${state.index+1} 問`);if(state.phase==='break')cue('なんやねん休憩！');}else if(state.hint!==before.hint&&!state.revealed&&state.phase==='play')cue(state.hint===2?'ぜんぶ公開！':'もう少し見せるよ！');if(state.revealed&&!before.revealed&&state.phase==='play'){$('.stage-foot')?.classList.add('answer-enter');cue('正解は…！');}state.scores.forEach((value,i)=>{if(value>before.scores[i]){if(state.phase==='break')cue('なんやねん賞！',true);else if(!state.bonusAwarded||before.bonusAwarded)cue('大正解！',true);const el=document.createElement('span');el.className='score-pop';el.textContent='+'+(value-before.scores[i]);document.querySelectorAll('.side .score')[i]?.append(el);setTimeout(()=>el.remove(),1500);}});if(state.bonusAwarded&&!before.bonusAwarded)cue('珍回答賞！',true);}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function headerMarkup(){return `<header class="topbar"><div class="brand">ナニコレ<b>!?</b><span>AI QUIZ SHOW</span></div><div class="top-actions"><button data-action="help" aria-label="操作ガイド">操作ガイド</button><button data-action="fullscreen">全画面</button>${!isHost?'<button data-action="host">司会者画面 ↗</button>':''}${state.phase!=='setup'?'<button class="restart-button" data-action="restart" aria-label="最初からやり直す">最初から</button>':''}</div></header>`;}
function score(i){const interactive=state.phase==='play'&&!isHost,body=`<span class="player">PLAYER ${i+1}</span><span class="name">${esc(cfg.names[i])}</span><span class="points">${state.scores[i]}<small>点</small></span>`;if(!interactive)return `<div class="score player-${i}">${body}</div>`;const done=state.awarded[i],label=done?'加点済み ✓':`正解 +${points()}点`;return `<button type="button" class="score score-choice player-${i}" data-action="award${i}" aria-label="${esc(cfg.names[i])} ${label}" ${done?'disabled':''}>${body}<span class="score-action">${label}</span></button>`;}
function setup(){return `<div class="start-grid"><section class="start-main"><span class="eyebrow">ひらめき × ヘンテコ画像</span><h1>何と何が<br><em>合体した!?</em></h1><p class="lead">AIのナゾ画像を少しずつ公開。<br>先に見抜くのは、だれ？</p><div class="mystery" aria-hidden="true"><div class="mystery-box">?</div><span class="times">×</span><div class="mystery-box">?</div></div><button class="yellow start-button" data-action="start" ${!assetsReady?'disabled':''}><span>${assetsReady?'クイズをはじめる':'画像を準備しています…'}</span><span>→</span></button></section><div class="start-side"><section class="paper"><h2>今日のチャレンジャー</h2><div class="players">${playerIds().map(i=>`<div><label for="name${i}">PLAYER ${i+1}</label><input id="name${i}" maxlength="12" value="${esc(cfg.names[i])}" aria-label="プレイヤー${i+1}の名前"></div>`).join('')}</div></section><section class="paper"><h2>早くわかるほど、高得点。</h2><div class="rule-row"><span class="rule-num">01</span><div><strong>「何」と「何」か、2つ答えよう</strong><p>画像は3段階。わからなければ次のヒント！</p><div class="point-badges"><span>最初 3点</span><span>次 2点</span><span>全体 1点</span></div></div></div><div class="rule-row"><span class="rule-num">02</span><div><strong>「せーの！」の問題は3人で回答</strong><p>答えを決めて発表。全員正解もOK。珍回答賞もあり。3問ごとに「なんやねん休憩」！</p></div></div><div class="rule-row"><span class="rule-num">03</span><div><strong>最後は得点2倍！</strong><p>30問から10問を抽選。休憩も30種類から3回。最後まで逆転のチャンス。</p></div></div></section><div class="start-footer"><span>30問から10問を抽選</span><button class="light" data-action="settings">撮影前の設定</button></div></div></div><p class="asset-status ${assetError?'error':''}">${assetError?'画像を読み込めません。ZIPをすべて展開し直してから開いてください。':assetsReady?'画像の準備ができました。通信なしで遊べます。':'問題画像を読み込み中です。'}</p>`;}
function stage(){const q=question();return `<div class="game-layout"><section class="stage"><div class="stage-head"><div class="question-meta"><div class="q-number">Q${String(state.index+1).padStart(2,'0')} <small>/ ${cfg.order.length}</small></div><div><strong>${isFinal()?'最終問題 · 得点2倍':q.simultaneous?'せーので回答':q.level}</strong><p>${MODES[mode()]}</p></div></div><div class="prize ${isFinal()?'final':''}">正解で <b>${points()}</b> 点</div></div><div class="stage-body"><div class="image-frame" id="question-frame"><img id="question-image" src="${asset(q.id)}" alt="${state.revealed?esc(q.answer):'何と何が合体したかを当てる問題画像'}" draggable="false"><div class="tile-cover" id="tiles" aria-hidden="true"></div><div class="frame-caption">${state.revealed?'正解発表':state.hint===2?'全体公開！':`ヒント ${state.hint+1} / 3`}</div></div></div><div class="stage-foot">${state.revealed?`<span class="answer-label">ANSWER</span><h2>${esc(q.answer)}</h2><p>${esc(q.talk)}</p>`:`<h2>${q.simultaneous?'答えを決めたら、せーので発表！':'何と何が、合体した？'}</h2><p>${state.verbal?esc(q.hint):state.hint===2?'2つの名前を答えてね。言い換えもOK！':q.simultaneous?'3人の答えを聞いたら、正解者のカードをタップ（複数OK）。':`正解した人のカードをタップ。いまなら${points()}点！`}</p>`}</div></section><aside class="side">${playerIds().map(score).join('')}<div class="hint-track"><h3>早くわかるほど高得点</h3>${['ちょい見せ','もう少し！','ぜんぶ公開'].map((label,i)=>`<div class="step ${i===state.hint?'active':i<state.hint?'done':''}"><span>${i+1}. ${label}</span><b>${(3-i)*(isFinal()?2:1)}点</b></div>`).join('')}</div><div class="audience-note">${isFinal()?'最後の1問。<br>ひらめきで逆転だ！':q.simultaneous?'テレビの前のみんなも<br>せーので答えてね！':'見ているみんなも<br>いっしょに考えよう！'}</div></aside></div><div class="round-dots" aria-label="問題の進行">${cfg.order.map((_,i)=>`<span class="${i<state.index?'done':i===state.index?'active':''}"></span>`).join('')}</div>${audienceControls()}`;}
function audienceControls(){return `<div class="controls">${!state.revealed?`<button class="primary" data-action="hint" ${state.hint===2?'disabled':''}>次のヒント <small>SPACE</small></button><button class="light" data-action="reveal">答えを公開 <small>A</small></button>`:`<button class="primary" data-action="next">${[2,5,8].includes(state.index)?'なんやねん休憩へ':state.index===4?'中間発表へ':isFinal()?'結果発表へ':'次の問題'} →</button>`}<span class="spacer"></span><button data-action="undo">1つ戻す</button><button data-action="record">撮影表示</button><button class="light" data-action="togglehost">司会操作</button></div><p class="shortcut-line">正解者のカードを押して加点 ／ 同時正解なら複数押せます ／ SPACE 進行</p>${hostVisible?hostPanel():''}`;}
function standings(){return `<div class="standings">${playerIds().map(i=>`<div class="standing"><strong>${esc(cfg.names[i])}</strong><b>${state.scores[i]}<small> 点</small></b></div>`).join('')}</div>`;}
function breakScore(i){const done=state.breakAwarded[i],body=`<span class="player">PLAYER ${i+1}</span><span class="name">${esc(cfg.names[i])}</span><span class="points">${state.scores[i]}<small>点</small></span>`;if(isHost)return `<div class="score player-${i}">${body}</div>`;return `<button type="button" class="score score-choice player-${i}" data-action="breakAward${i}" aria-label="${esc(cfg.names[i])} ${done?'加点済み':'なんやねん賞 +1点'}" ${done?'disabled':''}>${body}<span class="score-action">${done?'加点済み ✓':'なんやねん賞 +1'}</span></button>`;}
function breakView(){const n=Math.floor(state.index/3)-1,b=BREAKS[cfg.breakOrder[n]];return `<section class="break-screen break-${n}"><div class="break-top"><div class="break-kicker"><span class="break-tag">BREAK ${String(n+1).padStart(2,'0')} / 03</span><span>3問ごとの、なんやねん休憩。</span></div><span class="break-prize">1人ずつ <b>+1点</b></span></div><div class="break-main"><div class="break-symbol" aria-hidden="true">${b.icon}</div><p class="break-label">${esc(b.label)}</p><h1>${esc(b.question)}</h1><p class="break-direction">${esc(b.direction)}</p><p class="break-joke">${esc(b.tag)}</p></div><div class="break-bottom"><p class="break-award-note">面白かった人のカードをタップして +1点。何人でもOK！</p><div class="break-scores side">${playerIds().map(breakScore).join('')}</div><div class="break-controls"><button class="primary" data-action="breakNext">${state.index===9?'最終問題へ →':'本編にもどる →'}</button><button data-action="undo">1つ戻す</button><button data-action="record">撮影表示</button></div></div></section>`;}
function interlude(){let content='';if(state.phase==='intro')content=`<span class="eyebrow">READY TO GUESS?</span><h1>何と何が合体した？<br>2つ答えてね！</h1><p>早く当てると 3点 → 2点 → 1点<br>せーの問題は3人ともチャンス。3問ごとに、なんやねん休憩！</p><button class="yellow" data-action="countdown">準備OK！ スタート →</button>`;
 if(state.phase==='countdown')content=`<span class="eyebrow">いくよ！</span><div class="big-number">${countdownValue}</div><p>何と何が合体したか、当ててね！</p><button data-action="skipcount">すぐ始める</button>`;
 if(state.phase==='mid')content=`<span class="eyebrow">HALFTIME</span><h1>ここまでの得点は…！</h1>${standings()}<p>${new Set(state.scores).size===1?'まさかの全員同点！ 勝負は後半へ。':`トップは${state.scores.map((score,i)=>score===Math.max(...state.scores)?esc(cfg.names[i]):null).filter(Boolean).join('・')}！ まだまだ勝負はこれから！`}</p><button class="yellow" data-action="continue">後半へ →</button>`;
 if(state.phase==='final')content=`<span class="eyebrow">FINAL QUESTION</span><h1>最後の問題は<br><span style="color:var(--yellow)">得点2倍！</span></h1><p>最初で当てれば 6点。次は4点、全体なら2点。<br>最後のひらめき、見せてくれ！</p><button class="yellow" data-action="continue">最終問題へ →</button>`;
 if(state.phase==='results'){let leaders=state.scores.map((score,i)=>score===Math.max(...state.scores)?esc(cfg.names[i]):null).filter(Boolean);let winner=leaders.length===PLAYER_COUNT?'3人とも優勝！':`${leaders.join('・')}の優勝！`;content=`<span class="winner">本日のひらめきチャンピオン</span><h1>${winner}</h1>${standings()}<p>いちばん笑った画像は、どれだった？<br>見ているみんなは、何問わかった？</p><button class="yellow" data-action="restart">もう一度あそぶ</button><button class="light" data-action="review">今日のお題を振り返る</button>`;}
 return `<section class="interlude">${content}</section>${state.phase!=='countdown'?`<div class="controls"><button data-action="undo">1つ戻す</button><span class="spacer"></span><button data-action="record">撮影表示</button></div>`:''}`;}
function hostPanel(){
 if(state.phase==='break'){
  const b=BREAKS[cfg.breakOrder[Math.floor(state.index/3)-1]];
  return `<section class="host-panel"><div class="host-heading"><h2>司会者の操作 · なんやねん休憩</h2></div><div class="host-info"><p><strong>${esc(b.label)}</strong>${esc(b.question)}</p><p>面白かった人へカードで +1点。複数人に入れてOK。全員への加点もできます。</p></div><div class="controls">${playerIds().map(i=>`<button class="player-button player-${i}" data-action="breakAward${i}" ${state.breakAwarded[i]?'disabled':''}>${esc(cfg.names[i])} ${state.breakAwarded[i]?'加点済み':'+1点'}</button>`).join('')}<button class="primary" data-action="breakNext">${state.index===9?'最終問題へ':'本編へ'} →</button></div><div class="corrections"><button data-action="undo">1つ戻す</button></div></section>`;
 }
 const q=question();
 return `<section class="host-panel"><div class="host-heading"><h2>司会者の操作</h2><span class="badge">出演者には見せないでね</span></div><div class="host-info"><p><strong>正解 · 第${state.index+1}問</strong>${esc(q.answer)}</p><p><strong>会話のきっかけ</strong>${esc(q.talk)}</p><p><strong>困ったときの追加ヒント</strong>${esc(q.hint)}</p><p><strong>今回のルール</strong>${q.simultaneous?'3人の答えを聞いたら、正解者のカードを全員分クリック。最初のクリックで答えも公開。':'各ヒントで1人1回答。同時に正解した人には全員加点。'}<br>表現が違っても意味が合っていれば正解。</p></div>${state.phase==='play'?`<div class="controls"><button class="primary" data-action="hint" ${state.revealed||state.hint===2?'disabled':''}>次のヒント</button><button data-action="verbal" ${state.revealed?'disabled':''}>言葉のヒント</button><button class="yellow" data-action="reveal" ${state.revealed?'disabled':''}>答えを公開</button><button data-action="skip">この問題をスキップ</button></div><div class="controls">${playerIds().map(i=>`<button class="player-button player-${i}" data-action="award${i}" ${state.awarded[i]?'disabled':''}>${esc(cfg.names[i])} ${state.awarded[i]?'加点済み':`正解 +${points()}点`}</button>`).join('')}<button class="primary" data-action="next" ${!state.revealed?'disabled':''}>次へ →</button></div>${q.bonus?`<div class="bonus-control"><strong>珍回答賞　+1点</strong><span>3人の回答を聞いて、いちばん面白い答えに1回だけ。</span><div class="controls">${playerIds().map(i=>`<button class="player-button player-${i}" data-action="bonus${i}" ${state.bonusAwarded?'disabled':''}>${esc(cfg.names[i])} +1</button>`).join('')}</div></div>`:''}`:`<div class="controls"><button class="primary" data-action="advance">${state.phase==='setup'?'開始する':state.phase==='results'?'もう一度あそぶ':'進行する →'}</button></div>`}<div class="corrections"><small>得点修正</small>${playerIds().map(i=>`<span>${esc(cfg.names[i])}</span><button data-action="adjust${i}-" aria-label="${esc(cfg.names[i])} 1点減らす">−1</button><button data-action="adjust${i}+" aria-label="${esc(cfg.names[i])} 1点増やす">＋1</button>`).join('')}<button data-action="undo">1つ戻す</button></div></section>`;
}
function render(){document.body.classList.toggle('recording',recording&&!isHost);document.body.classList.toggle('host-screen',isHost);if(isHost){$('#app').innerHTML=`<div class="shell">${headerMarkup()}<div class="host-only-title">司会者専用 · 本番画面は別ウィンドウです / ${state.phase==='play'?`第${state.index+1}問・ヒント${state.hint+1}`:({setup:'準備中',intro:'ルール説明',countdown:'カウントダウン',break:'なんやねん休憩',mid:'中間発表',final:'最終問題前',results:'結果発表'}[state.phase])}</div><div class="scores-inline">${playerIds().map(score).join('')}</div>${hostPanel()}<p class="shortcut-line">SPACE 進行 ／ A 答え ／ 1・2・3 正解 ／ U 取り消し</p></div>`;return;}
 $('#app').innerHTML=`<main class="shell">${headerMarkup()}${state.phase==='setup'?setup():state.phase==='play'?stage():state.phase==='break'?breakView():interlude()}</main>`;if(state.phase==='play')applyReveal($('#question-image'),$('#tiles'),question(),state.hint,state.revealed);}
function seeded(n){let x=Math.sin((state.seed+1)*971+n*317)*43758.5453;return x-Math.floor(x);}
function spot(q){return cfg.spots[q.id]||q.spots[Math.floor(state.seed*q.spots.length)%q.spots.length];}
const silhouettes={},loadedImages={};
function silhouette(src,id){if(silhouettes[id])return silhouettes[id];const im=loadedImages[id];if(!im||!im.naturalWidth)return 'data:image/gif;base64,R0lGODlhAQABAAD/ACwAAAAAAQABAAACADs=';try{const c=document.createElement('canvas');c.width=c.height=500;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(im,0,0,500,500);const data=cx.getImageData(0,0,500,500),d=data.data;const samples=[0,499,499*500,500*500-1].map(p=>[d[p*4],d[p*4+1],d[p*4+2]]);const seen=new Uint8Array(250000),queue=new Int32Array(250000);let head=0,tail=0;const add=(p)=>{if(p<0||p>=250000||seen[p])return;seen[p]=1;let j=p*4;let delta=Math.min(...samples.map(s=>Math.hypot(d[j]-s[0],d[j+1]-s[1],d[j+2]-s[2])));if(delta<65||d[j+3]<20)queue[tail++]=p;};for(let n=0;n<500;n++){add(n);add(249500+n);add(n*500);add(n*500+499);}while(head<tail){const p=queue[head++];d[p*4+3]=0;if(p%500)add(p-1);if(p%500<499)add(p+1);add(p-500);add(p+500);}for(let n=0;n<250000;n++){d[n*4]=21;d[n*4+1]=36;d[n*4+2]=77;}cx.putImageData(data,0,0);silhouettes[id]=c.toDataURL();return silhouettes[id];}catch{return src;}}
function applyReveal(img,tiles,q,hint,revealed,overrideMode){if(!img)return;img.src=asset(q.id);img.parentElement.style.backgroundImage='none';const m=overrideMode||cfg.modes[q.id]||q.mode;const [x,y]=spot(q);img.style.clipPath='none';img.style.transform='none';img.style.filter='none';img.style.transformOrigin=`${x*100}% ${y*100}%`;img.parentElement.style.background=m==='silhouette'?'#f5d969':'#14244e';tiles.innerHTML='';if(revealed||hint===2)return;
 if(m==='window'){const size=hint===0?.16:.32;const left=Math.max(0,Math.min(1-size,x-size/2)),top=Math.max(0,Math.min(1-size,y-size/2));img.style.clipPath=`inset(${top*100}% ${(1-left-size)*100}% ${(1-top-size)*100}% ${left*100}% round 12px)`;}
 if(m==='zoom'){img.style.transform=`scale(${hint===0?6:3.7})`;}
 if(m==='tiles'){const focus=Math.min(15,Math.floor(y*4)*4+Math.floor(x*4));const first=cfg.spots[q.id]?[focus]:(q.firstTiles||[focus]);const rest=Array.from({length:16},(_,i)=>i).filter(i=>!first.includes(i)).sort((a,b)=>seeded(a)-seeded(b));const order=[...first,...rest],count=hint===0?first.length:4;tiles.innerHTML=Array.from({length:16},(_,i)=>`<span class="${order.indexOf(i)<count?'open':''}"></span>`).join('');}
 if(m==='silhouette'){img.src=silhouette(asset(q.id),q.id);img.style.clipPath=hint===0?'inset(25% 25% 25% 25% round 10px)':'inset(12% 16% 12% 16% round 10px)';}
}
function freshQuestion(){state.hint=0;state.revealed=false;state.awarded=[false,false,false];state.selected=[false,false,false];state.bonusAwarded=false;state.seed=Math.random();state.verbal=false;}
function next(){if(state.index===cfg.order.length-1){state.phase='results';return;}state.index++;freshQuestion();state.breakAwarded=[false,false,false];state.phase=state.index===5?'mid':[3,6,9].includes(state.index)?'break':'play';}
function beginCountdown(){clearInterval(countdownTimer);countdownValue=3;change(()=>state.phase='countdown');countdownTimer=setInterval(()=>{countdownValue--;if(countdownValue<=0){clearInterval(countdownTimer);change(()=>state.phase='play');}else{render();sync();}},850);}
function act(action){if(isHost&& !['fullscreen','help'].includes(action)){if(!window.opener||window.opener.closed){toast('本番画面が閉じています。本番画面を開き直してください。');return;}window.opener.postMessage({kind:'quiz-action',action},location.origin==='null'?'*':location.origin);return;}
 if(action==='help')return help();if(action==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('ブラウザの全画面ボタンを使ってください。'));return;}
 if(action==='host'){hostWindow=window.open(location.pathname+'?host=1','nanikore-host','width=1000,height=850');if(!hostWindow)toast('ポップアップを許可すると司会者画面を開けます。');else toast('司会者画面を開きました。出演者に見えない画面へ移動してください。');return;}
 if(action==='record'){recording=!recording;hostVisible=false;render();if(recording)toast('撮影表示 · R キーで操作を戻せます');return;}if(action==='togglehost'){hostVisible=!hostVisible;render();return;}
 if(action==='settings')return settings();if(action==='review')return settings(true);
 if(action==='undo'){clearInterval(countdownTimer);const prev=history.pop();if(prev){cfg=prev.cfg;state=prev.state;if(state.phase==='countdown')state.phase='intro';save();render();sync();}else toast('戻せる操作はありません');return;}
 if(action.startsWith('adjust')){const i=Number(action[6]),delta=action.endsWith('+')?1:-1;change(()=>state.scores[i]=Math.max(0,state.scores[i]+delta));return;}
 if(action==='restart'){return confirmDialog('最初からやり直しますか？','途中経過と得点を消して、新しい10問を抽選します。名前は残ります。',()=>{clearInterval(countdownTimer);history=[];cfg.order=drawQuestions();cfg.breakOrder=drawBreaks();state={phase:'setup',index:0,hint:0,scores:[0,0,0],revealed:false,awarded:[false,false,false],selected:[false,false,false],bonusAwarded:false,breakAwarded:[false,false,false],seed:Math.random(),verbal:false};recording=false;hostVisible=false;save();render();sync();},'新しい10問でやり直す');}
 if(action==='advance'){if(state.phase==='setup')return act('start');if(state.phase==='intro')return act('countdown');if(state.phase==='countdown')return act('skipcount');if(state.phase==='break')return act('breakNext');if(['mid','final'].includes(state.phase))return act('continue');if(state.phase==='results')return act('restart');return act(state.revealed?'next':'hint');}
 if(action==='start'&&state.phase==='setup'){if(!assetsReady){toast('画像の読み込みを待ってください');return;}if($('#name0'))cfg.names=playerIds().map(i=>$('#name'+i).value.trim()||`プレイヤー${i+1}`);change(()=>state.phase='intro');return;}
 if(action==='countdown'&&state.phase==='intro')return beginCountdown();if(action==='skipcount'&&state.phase==='countdown'){clearInterval(countdownTimer);change(()=>state.phase='play');return;}
 if(action==='continue'&&['mid','final'].includes(state.phase)){change(()=>state.phase='play');return;}
 if(state.phase==='break'){
  if(action.startsWith('breakAward')){const i=Number(action.slice(-1));if(playerIds().includes(i)&&!state.breakAwarded[i]){change(()=>{state.scores[i]++;state.breakAwarded[i]=true;});confetti();}return;}
  if(action==='breakNext'){change(()=>state.phase=state.index===9?'final':'play');return;}
  return;
 }
 if(state.phase!=='play')return;
 if(action==='hint'){if(!state.revealed&&state.hint<2)change(()=>{state.hint++;state.verbal=false;});else if(state.hint===2&&!state.revealed)toast('全体公開中です。A キーで答えを発表できます');return;}
 if(action==='verbal'&&!state.revealed){change(()=>{state.verbal=!state.verbal;state.hint=2;});return;}
 if(action==='reveal'&&!state.revealed){change(()=>state.revealed=true);return;}
 if(action.startsWith('bonus')){const i=Number(action.slice(-1));if(question().bonus&&playerIds().includes(i)&&!state.bonusAwarded)change(()=>{state.scores[i]++;state.bonusAwarded=true;});return;}
 if(action.startsWith('award')){const i=Number(action.slice(-1));if(!playerIds().includes(i)||state.awarded[i])return;change(()=>{state.revealed=true;state.scores[i]+=points();state.awarded[i]=true;});confetti();return;}
 if(action==='next'&&state.revealed){change(next);if(state.phase==='results')confetti();return;}
 if(action==='skip')confirmDialog('この問題をスキップしますか？','得点を追加せず、次の問題へ進みます。',()=>change(next));
}
function confetti(){if(isHost)return;const box=document.createElement('div');box.className='confetti';box.innerHTML=Array.from({length:34},(_,i)=>`<i style="left:${(i*37)%100}%;animation-delay:${i%5*.055}s"></i>`).join('');($('.stage')||$('.interlude')||$('.break-screen')||$('#app')).append(box);setTimeout(()=>box.remove(),2600);}
function dialog(html){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.innerHTML=html;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());return d;}
function confirmDialog(title,desc,fn,confirmLabel='進める'){const d=dialog(`<h2>${esc(title)}</h2><p class="dialog-desc">${esc(desc)}</p><div class="dialog-actions"><button data-close>やめる</button><button class="primary" id="confirm-ok">${esc(confirmLabel)}</button></div>`);d.querySelector('#confirm-ok').onclick=()=>{d.close();fn();};}
function help(){dialog(`<div class="dialog-top"><h2>操作ガイド</h2><button data-close>閉じる</button></div><ol class="help-list"><li>名前を入力して「クイズをはじめる」。</li><li>SPACE でヒントを追加。正解した人のカードを押して加点。同時正解なら全員押す。</li><li>せーの問題は、3人の答えを聞いてから正解者のカードを押す。最初のクリックで答えも公開。複数人に加点できます。</li><li>正解発表の後は SPACE で次へ。3問ごとの「なんやねん休憩」は3人で大喜利。回答後、面白かった人のカードで何人でも +1点。賞なしでも進めます。</li><li>間違えたら U で戻す。</li><li>途中からやり直すときは、画面右上の「最初から」。</li><li>R で操作ボタンを隠す撮影表示。もう一度 R で戻る。</li><li>司会者画面を別のディスプレイへ移動すると、正解を見ながら進行できます。</li></ol><p class="dialog-desc">F：全画面 / A：答え公開 / 1・2・3：正解 / U：1つ戻す<br>ヒントは自動で進みません。珍回答や会話が出たら、そのまま待ってOK。<br>途中経過はこのブラウザに自動保存。画像はローカルに同梱されています。</p>`);}
function settings(review=false){const draft=clone(cfg);const d=dialog(`<div class="dialog-top"><h2>${review?'今日のお題':'撮影前の設定'}</h2><button data-close>閉じる</button></div><p class="dialog-desc">${review?'印象に残った画像を選んで、感想を聞いてみよう。':'この画面には正解が出ます。撮影前に確認してください。上下で並べ替え。最後の位置が得点2倍になります。'}</p><div class="question-list"></div><div id="preview-area"></div>${!review?'<div class="dialog-actions"><button data-close>キャンセル</button><button class="primary" id="save-settings">設定を保存</button></div>':''}`);
 const draw=()=>{d.querySelector('.question-list').innerHTML=draft.order.map((id,i)=>{const q=QUESTIONS.find(q=>q.id===id);return `<div class="q-row"><img src="${asset(id)}" alt="${esc(q.answer)}"><div><strong>${i+1}. ${esc(q.answer)}</strong><small>${i===9?'得点2倍':q.simultaneous?'せーので回答':'早押し'} · <button data-preview="${id}">画像を確認</button></small></div>${!review?`<select data-mode="${id}" aria-label="${esc(q.answer)}の見せ方">${Object.entries(MODES).map(([k,v])=>`<option value="${k}" ${k===(draft.modes[id]||q.mode)?'selected':''}>${v}</option>`).join('')}</select><div class="arrows"><button data-up="${i}" ${i===0?'disabled':''} aria-label="上へ">↑</button><button data-down="${i}" ${i===9?'disabled':''} aria-label="下へ">↓</button></div>`:''}</div>`;}).join('');};draw();
 function preview(id){previewId=id;const q=QUESTIONS.find(q=>q.id===id),sp=draft.spots[id]||q.spots[0];d.querySelector('#preview-area').innerHTML=`<div class="preview-box"><p><strong>${esc(q.answer)}</strong> · ${review?'全体画像':'最初のヒントを確認'}</p><div class="image-frame"><img id="preview-image" src="${asset(id)}" alt="${esc(q.answer)}"><div class="tile-cover" id="preview-tiles"></div></div>${!review?`<div class="range-row"><label for="spot-x">横の位置</label><input id="spot-x" type="range" min=".15" max=".85" step=".01" value="${sp[0]}"><label for="spot-y">縦の位置</label><input id="spot-y" type="range" min=".15" max=".85" step=".01" value="${sp[1]}"></div><p>小窓・ズーム・タイルの最初の位置を調整できます。</p>`:''}</div>`;if(!review){const refresh=()=>{draft.spots[id]=[Number(d.querySelector('#spot-x').value),Number(d.querySelector('#spot-y').value)];const old=cfg;cfg=draft;applyReveal(d.querySelector('#preview-image'),d.querySelector('#preview-tiles'),q,0,false);cfg=old;};d.querySelector('#spot-x').oninput=refresh;d.querySelector('#spot-y').oninput=refresh;refresh();}d.querySelector('#preview-area').scrollIntoView({block:'nearest'});}
 d.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.up!==undefined){let i=Number(b.dataset.up);[draft.order[i-1],draft.order[i]]=[draft.order[i],draft.order[i-1]];draw();}if(b.dataset.down!==undefined){let i=Number(b.dataset.down);[draft.order[i+1],draft.order[i]]=[draft.order[i],draft.order[i+1]];draw();}if(b.dataset.preview)preview(b.dataset.preview);});d.addEventListener('change',e=>{if(e.target.dataset.mode){draft.modes[e.target.dataset.mode]=e.target.value;if(previewId===e.target.dataset.mode)preview(previewId);}});
 if(!review)d.querySelector('#save-settings').onclick=()=>{cfg=draft;save();sync();d.close();render();toast('問題の設定を保存しました');};}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.hasAttribute('data-close'))return b.closest('dialog').close();if(b.dataset.action)act(b.dataset.action);});
document.addEventListener('change',e=>{if(/^name[0-2]$/.test(e.target.id)){cfg.names[Number(e.target.id.slice(-1))]=e.target.value.trim()||'プレイヤー';save();sync();}});
document.addEventListener('keydown',e=>{if(e.repeat||e.ctrlKey||e.metaKey||e.altKey||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;const keys={' ':'advance',a:'reveal','1':'award0','2':'award1','3':'award2',u:'undo',r:'record',f:'fullscreen'};const action=keys[e.key.toLowerCase()];if(action){e.preventDefault();act(action);}});
window.addEventListener('message',e=>{if(isHost){if(e.source!==window.opener)return;if(e.data?.kind==='quiz-state'){cfg=e.data.cfg;state=e.data.state;history=e.data.history;assetsReady=e.data.assetsReady;assetError=e.data.assetError;render();}}else{if(e.source!==hostWindow)return;if(e.data?.kind==='quiz-ready')sync();if(e.data?.kind==='quiz-action')act(e.data.action);}});
async function preload(){const results=await Promise.all(QUESTIONS.map(q=>new Promise(resolve=>{const im=new Image();im.onload=()=>{loadedImages[q.id]=im;resolve(true);};im.onerror=()=>resolve(false);im.src=asset(q.id);})));assetsReady=results.every(Boolean);assetError=!assetsReady;render();sync();}
render();if(isHost){if(window.opener)window.opener.postMessage({kind:'quiz-ready'},location.origin==='null'?'*':location.origin);else toast('本番画面の「司会者画面」から開いてください。');}else preload();
